(() => {
  const config=globalThis.ATLAS_CONFIG||{}, gate=document.querySelector('#auth-gate');
  let resolveReady;
  const ready=new Promise(resolve=>{resolveReady=resolve;});
  const auth={currentUser:null,ready};globalThis.AtlasAuth=auth;
  if(config.accounts!==true){document.body.classList.remove('auth-pending');resolveReady(null);return;}

  const b64decode=value=>Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'=')),c=>c.charCodeAt(0));
  const b64encode=value=>{const bytes=new Uint8Array(value);let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
  const convertOptions=(options,creation)=>{const publicKey={...options,challenge:b64decode(options.challenge)};if(creation)publicKey.user={...options.user,id:b64decode(options.user.id)};for(const key of ['allowCredentials','excludeCredentials'])if(options[key])publicKey[key]=options[key].map(item=>({...item,id:b64decode(item.id)}));return publicKey;};
  const serializeCredential=credential=>{const response={clientDataJSON:b64encode(credential.response.clientDataJSON)};for(const key of ['attestationObject','authenticatorData','signature','userHandle'])if(credential.response[key])response[key]=b64encode(credential.response[key]);const result={id:credential.id,rawId:b64encode(credential.rawId),type:credential.type,response};if(typeof credential.response.getTransports==='function')result.response.transports=credential.response.getTransports();if(credential.authenticatorAttachment)result.authenticatorAttachment=credential.authenticatorAttachment;if(credential.getClientExtensionResults)result.clientExtensionResults=credential.getClientExtensionResults();return result;};
  const api=async(route,payload)=>{const response=await fetch(route,{method:payload===undefined?'GET':'POST',cache:'no-store',headers:payload===undefined?{}:{'content-type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload)});const data=await response.json().catch(()=>({error:'Risposta del server non valida.'}));if(!response.ok)throw Error(data.error||'Operazione non riuscita.');return data;};
  function view(message=''){
    gate.hidden=false;
    gate.innerHTML=`<div class="auth-card"><img class="auth-mark" src="/icons/master-atlas-logo-v2.png" alt=""><div class="eyebrow">BIOSCIENCES · 2027</div><h1 id="auth-title">Il tuo atlante, sempre con te.</h1><p class="auth-intro">Accedi con il tuo profilo per ritrovare percorsi, università e candidature su ogni dispositivo.</p><form id="auth-form"><label for="auth-username">Nome utente</label><input id="auth-username" name="username" autocomplete="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,31}" required placeholder="es. michele_bio"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required placeholder="Almeno 12 caratteri"><label class="auth-remember"><input id="auth-remember" type="checkbox" checked><span><strong>Resta connesso</strong><small>L’accesso si rinnova mentre usi l’app.</small></span></label><p id="auth-message" class="auth-message" role="status" aria-live="polite">${message}</p><div class="auth-actions"><button id="auth-login" type="button" class="button">Accedi</button><button id="auth-register" type="button" class="button primary">Crea profilo</button><button id="auth-passkey" type="button" class="button auth-passkey-button">Usa una passkey</button></div></form><p class="auth-footnote">La password viene conservata solo come hash protetto. Puoi aggiungere una passkey al profilo per accedere con Face ID, impronta o il gestore passkey del tuo dispositivo.</p></div>`;
    document.querySelector('#auth-login').addEventListener('click',loginPassword);
    document.querySelector('#auth-register').addEventListener('click',registerPassword);
    document.querySelector('#auth-passkey').addEventListener('click',loginPasskey);
    document.querySelector('#auth-form').addEventListener('submit',event=>{event.preventDefault();loginPassword();});
  }
  const usernameInput=()=>document.querySelector('#auth-username').value.trim().toLowerCase();
  const remember=()=>document.querySelector('#auth-remember').checked;
  const passwordInput=()=>document.querySelector('#auth-password').value;
  const setMessage=message=>{const el=document.querySelector('#auth-message');if(el)el.textContent=message;};
  async function busy(action){const buttons=[...gate.querySelectorAll('button')];buttons.forEach(button=>button.disabled=true);setMessage('Verifica in corso…');try{await action();}catch(error){setMessage(error.message||'Operazione non riuscita.');}finally{buttons.forEach(button=>button.disabled=false);}}
  function activate(user){auth.currentUser=user;gate.hidden=true;document.body.classList.remove('auth-pending');const name=document.querySelector('#account-name');name.textContent=user.username;name.hidden=false;for(const id of ['account-add-passkey','account-manage-profile','account-logout']){const element=document.querySelector(`#${id}`);if(element)element.hidden=false;}resolveReady(user);}
  async function loginPassword(){const username=usernameInput(),password=passwordInput();if(!username||!password){setMessage('Inserisci nome utente e password.');return;}await busy(async()=>activate((await api('/api/auth/password/login',{username,password,remember:remember()})).user));}
  async function registerPassword(){const username=usernameInput(),password=passwordInput();if(!username||!password){setMessage('Scegli un nome utente e una password.');return;}if(password.length<12){setMessage('La password deve contenere almeno 12 caratteri.');return;}await busy(async()=>activate((await api('/api/auth/password/register',{username,password,remember:remember()})).user));}
  async function startPasskey(route,creation=false){const {flowId,publicKey}=await api(route,{username:usernameInput()});const credential=creation?await navigator.credentials.create({publicKey:convertOptions(publicKey,true)}):await navigator.credentials.get({publicKey:convertOptions(publicKey,false)});if(!credential)throw Error('Operazione annullata.');return{flowId,response:serializeCredential(credential)};}
  async function loginPasskey(){const username=usernameInput();if(!username){setMessage('Inserisci prima il nome utente del profilo.');document.querySelector('#auth-username').focus();return;}if(!window.PublicKeyCredential){setMessage('Questo browser non supporta le passkey.');return;}await busy(async()=>{const flow=await startPasskey('/api/auth/login/options');const {user}=await api('/api/auth/login/verify',{...flow,remember:remember()});activate(user);});}

  const profileDialog=document.querySelector('#profile-dialog'), profileMessage=document.querySelector('#profile-message');
  const showProfileMessage=(message,error=false)=>{profileMessage.textContent=message;profileMessage.style.color=error?'#c45454':'';};
  document.querySelector('#account-manage-profile').addEventListener('click',()=>{const user=auth.currentUser;document.querySelector('#profile-new-username').value=user?.username||'';document.querySelector('#profile-delete-current').textContent=user?.username||'';document.querySelector('#profile-delete-confirm').value='';document.querySelector('#profile-rename-password').value='';document.querySelector('#profile-delete-password').value='';showProfileMessage('');profileDialog.showModal();});
  document.querySelector('#profile-close').addEventListener('click',()=>profileDialog.close());
  document.querySelector('#profile-rename-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;showProfileMessage('Aggiornamento…');try{const {user}=await api('/api/auth/profile/rename',{username:document.querySelector('#profile-new-username').value.trim().toLowerCase(),password:document.querySelector('#profile-rename-password').value});auth.currentUser=user;document.querySelector('#account-name').textContent=user.username;document.querySelector('#profile-delete-current').textContent=user.username;showProfileMessage('Nome utente aggiornato.');}catch(error){showProfileMessage(error.message||'Non è stato possibile rinominare il profilo.',true);}finally{button.disabled=false;}});
  document.querySelector('#profile-delete-form').addEventListener('submit',async event=>{event.preventDefault();if(document.querySelector('#profile-delete-confirm').value.trim()!=='ELIMINA'){showProfileMessage('Scrivi ELIMINA per confermare.',true);return;}if(!window.confirm(AtlasI18n.translate('Eliminare definitivamente il profilo e tutti i dati sincronizzati? Questa azione non si può annullare.')))return;const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;showProfileMessage('Eliminazione in corso…');try{await api('/api/auth/profile/delete',{confirm:'ELIMINA',password:document.querySelector('#profile-delete-password').value});const key=`master-atlas-2027-v2:${auth.currentUser.id}`;try{localStorage.removeItem(key);localStorage.removeItem(`${key}-recovery`);}catch{}location.reload();}catch(error){showProfileMessage(error.message||'Non è stato possibile eliminare il profilo.',true);}finally{button.disabled=false;}});
  document.querySelector('#account-add-passkey').addEventListener('click',async()=>{if(!window.PublicKeyCredential){alert(AtlasI18n.translate('Questo browser non supporta le passkey.'));return;}try{const {flowId,publicKey}=await api('/api/auth/passkeys/options',{});const credential=await navigator.credentials.create({publicKey:convertOptions(publicKey,true)});if(!credential)return;await api('/api/auth/passkeys/verify',{flowId,response:serializeCredential(credential)});alert(AtlasI18n.translate('Passkey aggiunta al profilo.'));}catch(error){alert(AtlasI18n.translate(error.message||'Non è stato possibile aggiungere la passkey.'));}});
  document.querySelector('#account-logout').addEventListener('click',async()=>{try{await api('/api/auth/logout',{});}finally{location.reload();}});
  view();api('/api/auth/session').then(({user})=>activate(user)).catch(error=>{if(error.message==='Failed to fetch')setMessage('Server non raggiungibile. Riprova tra poco.');});
})();
